import os, sys

OUT = r"<test folder>\outside.txt"
ROOT = r"<test folder>"
AUTH = r"<test folder>\authors_code"

def line(label, fn):
    try:
        print(f"{label}: OK -> {fn()!r}")
    except Exception as e:
        print(f"{label}: FAIL -> {type(e).__name__}: {e}")

print("=== os.scandir ===")
line("os.scandir ROOT", lambda: [e.name for e in os.scandir(ROOT)])

print("=== open dir as fd then listdir(fd) ===")
def fdlist():
    fd = os.open(ROOT, os.O_RDONLY)
    try:
        return os.listdir(fd)
    finally:
        os.close(fd)
line("listdir(fd)", fdlist)

print("=== import outside file as module ===")
def imp():
    sys.path.insert(0, AUTH)
    import importlib
    return importlib.import_module("solution").__doc__
line("import solution", imp)

print("=== runpy outside ===")
def rp():
    import runpy
    return runpy.run_path(os.path.join(AUTH, "solution.py"))
line("runpy solution.py", rp)

print("=== os.stat full metadata leak ===")
def st():
    s = os.stat(OUT)
    return dict(size=s.st_size, mtime=s.st_mtime, mode=oct(s.st_mode))
line("stat outside.txt", st)
line("stat solution.py", lambda: os.stat(os.path.join(AUTH, "solution.py")).st_size)

print("=== os.readlink / is dir junction ===")
line("readlink ROOT", lambda: os.readlink(ROOT))

print("=== read via io.open_code (used by import) ===")
def oc():
    return io_open_code(OUT).read()
def io_open_code(p):
    import io
    return io.open_code(p)
line("io.open_code", oc)
